import {dashboardAlerts} from '../core/dashboard-alerts.js?v=20261111-v15a';
import {salesReceived,expensesPaid} from '../core/dashboard-totals.js?v=20261111-v15a';
import {quoteReference,configSection,financialSummary,ledgerBalance,outstanding,today,round} from '../core/business.js?v=20261111-v15a';
export function install(ctx){
 const navigation={home:['Visão geral','home'],workflow:['Pedidos e produção','workflow'],quotes:['Orçamentos','quotes'],finance:['Financeiro','finance'],bank:['Extratos e conciliação','bank'],reports:['Relatórios','reports'],clients:['Clientes','clients'],products:['Produtos','products'],suppliers:['Fornecedores','clients'],assets:['Ativos e patrimônio','assets'],settings:['Configurações','settings'],users:['Usuários e acessos','users']};
 function toast(message){const n=ctx.$('#toast');n.textContent=message;n.className='show';clearTimeout(ctx.toastTimer);ctx.toastTimer=setTimeout(()=>n.className='',5000)}
 function shell(body){const previousMenu=ctx.$('.sidebar .nav'),menuScroll={top:previousMenu?.scrollTop||0,left:previousMenu?.scrollLeft||0};const custom=configSection(ctx.settings,'appearance').menu;const ordered=[...new Set([...custom,...Object.keys(navigation)])].filter(k=>navigation[k]&&ctx.routeAllowed(k));if(!custom.includes('suppliers')&&ordered.includes('suppliers')){ordered.splice(ordered.indexOf('suppliers'),1);ordered.splice(Math.max(0,ordered.indexOf('clients')+1),0,'suppliers')}const user=ctx.profile?.username||ctx.session?.user?.email||'Meu acesso';
  ctx.$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand-space">${ctx.brand()}<span class="workspace-tag">GESTÃO INTEGRADA</span></div><div class="nav-caption">SEU ESPAÇO DE TRABALHO</div><nav class="nav" aria-label="Menu principal" tabindex="0">${ordered.map(k=>ctx.navItem(k,navigation[k][0])).join('')}<button type="button" data-install-app>${ctx.icon('plus')}Instalar aplicativo</button></nav><div class="sidebar-foot"><span class="status-dot"></span> Avelon conectada<div class="muted">Sua operação, do pedido ao resultado.</div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><span>Avelon</span><span>/</span><strong>${ctx.esc(navigation[ctx.current]?.[0]||({quote:'Novo orçamento',view:'Documento do orçamento',receipt:'Recibo de pagamento'}[ctx.current])||'Cadastro')}</strong></div><div class="account"><span class="avatar">${ctx.esc(user.slice(0,2).toUpperCase())}</span><div><strong>${ctx.esc(user)}</strong><small>${ctx.profile?.is_owner?'Mestre Criador':ctx.profile?.role==='admin'?'Administrador':'Equipe Avelon'}</small></div><button class="ghost small" id="account" aria-label="Alterar senha">${ctx.icon('lock')}</button><button class="ghost small" id="logout" aria-label="Sair">${ctx.icon('logout')}</button></div></header><main class="content">${body}<footer class="bottom"><span>AVELON TÊXTIL · Onde sua imaginação ganha forma.</span><span>Gestão integrada · ${new Date().getFullYear()}</span></footer></main></div></div>`;
  document.body.dataset.density=configSection(ctx.settings,'appearance').density;
  document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{if(ctx.draft.length&&ctx.current==='quote'&&!confirm('Sair sem salvar este orçamento?'))return;ctx.draft=[];ctx.quoteDraftMeta=null;ctx.render(b.dataset.nav)});
  ctx.$('#logout').onclick=async()=>{try{await ctx.api('/auth/v1/logout',{method:'POST'})}finally{ctx.saveSession(null);ctx.profile=null;ctx.clients=[];ctx.suppliers=[];ctx.products=[];ctx.quotes=[];ctx.quoteVersions=[];ctx.business={};ctx.draft=[];ctx.login()}};ctx.$('#account').onclick=ctx.passwordDialog;
  document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>ctx.render(b.dataset.action));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>ctx.openQuote(b.dataset.view));ctx.applyPermissions();const menu=ctx.$('.sidebar .nav');if(menu){menu.scrollTop=menuScroll.top;menu.scrollLeft=menuScroll.left}
 }
 function head(title,subtitle,action='',label=''){return `<div class="pagehead"><div><div class="eyebrow">${ctx.esc(ctx.settings.company||'Avelon Têxtil')}</div><h1>${title}</h1><p>${subtitle}</p></div>${action&&ctx.routeAllowed(action)?`<button class="primary" data-action="${action}">${ctx.icon('plus')}${label}</button>`:''}</div>`}
 function empty(title,text){return `<div class="empty"><span class="empty-icon">${ctx.icon('quotes')}</span><strong>${title}</strong><p>${text}</p></div>`}
 function metric(label,value,detail,icon='finance',tone=''){return `<div class="metric ${tone}"><div><span>${label}</span><span class="metric-icon">${ctx.icon(icon)}</span></div><strong>${value}</strong><small>${detail}</small></div>`}

 function financeMetrics(){
  const {entries=[],settlements=[],accounts=[]}=ctx.business||{},end=today(),start=end.slice(0,7)+'-01';
  const summary=financialSummary(entries.filter(e=>!['transfer','equity'].includes(e.class)),settlements,start,end);
  const monthLabel=new Date(end+'T12:00:00-03:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric',timeZone:'America/Sao_Paulo'});
  const balance=round(accounts.reduce((n,a)=>n+ledgerBalance(a,entries,settlements,end),0));
  const receivable=round(entries.filter(e=>e.kind==='income').reduce((n,e)=>n+outstanding(e,settlements),0));
  const payable=round(entries.filter(e=>e.kind==='expense').reduce((n,e)=>n+outstanding(e,settlements),0));
  return `<section class="metrics dashboard-metrics">${metric('Vendas recebidas — total',ctx.money(salesReceived(entries,settlements,end)),'Histórico até hoje · sem rendimentos ou transferências','reports','sales-total')}${metric('Saídas realizadas — total',ctx.money(expensesPaid(entries,settlements,end)),'Pagamentos feitos · sem transferências entre contas','finance','expenses-total')}${metric('Saldo em conta',ctx.money(balance),'Contas e cofrinhos somados','bank')}${metric('A receber',ctx.money(receivable),'Valores pendentes','finance','positive')}${metric('A pagar',ctx.money(payable),'Compromissos em aberto','finance','negative')}<div class="metric month-movement"><div><span>Movimentação · ${ctx.esc(monthLabel)}</span><span class="metric-icon">${ctx.icon('reports')}</span></div><dl class="month-movement-values"><div><dt>Entradas</dt><dd>${ctx.money(summary.totals.income)}</dd></div><div><dt>Saídas</dt><dd>${ctx.money(summary.totals.expense)}</dd></div></dl><small>Transferências próprias e entre contas ficam separadas.</small></div></section>`;
 }
 function dashboard(){
  const {entries=[],settlements=[]}=ctx.business||{},end=today(),stages=configSection(ctx.settings,'production').stages;
  const alerts=dashboardAlerts(ctx.quotes,entries,settlements,stages,end);
  const label=q=>stages.find(s=>s.key===q.stage)?.label||q.stage;
  const quoteRow=q=>`<button class="dashboard-alert-row" data-view="${q.id}"><span><strong>#${quoteReference(q)} · ${ctx.esc(q.client_snapshot.name)}</strong><small>${ctx.esc(label(q))}${q.stage==='sent'?' · aguardando aprovação do cliente':''}${q.valid_until&&q.valid_until<end?' · validade vencida':''}</small></span><b>${ctx.money(q.total)}</b></button>`;
  const productionRow=q=>`<button class="dashboard-alert-row" data-alert-order="${q.id}"><span><strong>#${quoteReference(q)} · ${ctx.esc(q.client_snapshot.name)}</strong><small>${ctx.esc(label(q))}${q.delivery_date?' · entrega '+ctx.date(q.delivery_date)+(q.delivery_date<end?' · prazo vencido':''):''}</small></span>${ctx.icon('arrow')}</button>`;
  const financeRow=e=>`<button class="dashboard-alert-row" data-alert-entry="${e.id}"><span><strong>${e.kind==='expense'?'A pagar':'A receber'} · ${ctx.esc(e.description)}</strong><small class="${e.timing==='Vencido'?'error':''}">${e.timing} · ${ctx.date(e.due_date)}${e.party?' · '+ctx.esc(e.party):''}</small></span><b>${ctx.money(e.pending)}</b></button>`;
  const panel=(title,rows,renderer,route,note,emptyText)=>`<section class="panel alert-panel"><div class="panelhead"><h2>${title}</h2><span class="badge">${rows.length}</span></div><p class="alert-explanation">${note}</p>${rows.length?`<div class="dashboard-alert-list">${rows.slice(0,4).map(renderer).join('')}</div>`:`<p class="alert-empty">${emptyText}</p>`}<div class="alert-footer"><button class="secondary small" data-action="${route}">Ver ${route==='quotes'?'orçamentos':route==='workflow'?'pedidos':'financeiro'}${rows.length>4?' · '+rows.length+' registros':''}</button></div></section>`;
  const panels=[ctx.routeAllowed('quotes')?panel('Orçamentos em negociação',alerts.commercial,quoteRow,'quotes','Rascunhos, propostas enviadas e pedidos aguardando entrada. Enviado não significa produção iniciada.','Nenhum orçamento em negociação.'):'',ctx.routeAllowed('workflow')?panel('Produção e entrega',alerts.operational,productionRow,'workflow',`${alerts.production.length} em produção / prontos · ${alerts.ready.length} prontos para entrega. Suspensos e aguardando saldo são identificados à parte.`,'Nenhum pedido em produção ou entrega.'):'',ctx.routeAllowed('finance')?panel('Alertas financeiros',alerts.financial,financeRow,'finance',`${alerts.payables.length} ${alerts.payables.length===1?'conta a pagar':'contas a pagar'} · ${alerts.receivables.length} ${alerts.receivables.length===1?'conta a receber':'contas a receber'}. Valores em aberto, separados por vencimento.`,'Nenhuma conta a pagar ou receber em aberto.'):''].join('');
  ctx.shell(`${head('Clareza para decidir. Controle para crescer.','Sua empresa em movimento, do primeiro orçamento à última entrega.','quote','Novo orçamento')}<div class="overview-banner"><div><span class="eyebrow">OPERAÇÃO AVELON</span><h2>Produção e financeiro,<br>na mesma direção.</h2><p>Acompanhe os pedidos, antecipe compromissos e saiba o que já entrou no caixa.</p><div class="hero-buttons">${ctx.routeAllowed('workflow')?'<button class="accent" data-action="workflow">Abrir quadro de pedidos '+ctx.icon('arrow')+'</button>':''}${ctx.routeAllowed('finance')?'<button class="outline-light" data-action="finance">Ver financeiro</button>':''}</div></div><div class="banner-side overview-counts">${ctx.routeAllowed('quotes')?`<div><span>Orçamentos em negociação</span><strong>${alerts.commercial.length}</strong></div>`:''}${ctx.routeAllowed('workflow')?`<div><span>Pedidos em produção / prontos</span><strong>${alerts.production.length}</strong></div>`:''}${ctx.routeAllowed('finance')?`<div><span>Contas a pagar em aberto</span><strong>${alerts.payables.length}</strong></div><div><span>Contas a receber em aberto</span><strong>${alerts.receivables.length}</strong></div>`:''}</div></div>${financeMetrics()}<div class="dashboard-alerts" aria-label="Avisos por área">${panels}</div><section class="panel"><div class="panelhead"><h2>Orçamentos recentes</h2><button class="ghost small" data-action="quotes">Ver todos ${ctx.icon('arrow')}</button></div>${ctx.quoteTable(ctx.quotes.slice(0,5))}</section><div class="quick-links">${[['client-new','clients','Cadastrar cliente'],['product-new','products','Cadastrar produto'],['bank','bank','Importar extrato'],['reports','reports','Gerar relatório']].filter(([p])=>ctx.routeAllowed(p)).map(([p,i,t])=>`<button class="quick-link" data-action="${p}">${ctx.icon(i)}${t}${ctx.icon('arrow')}</button>`).join('')}</div>`);
  document.querySelectorAll('[data-alert-order]').forEach(el=>el.onclick=()=>ctx.orderDialog(el.dataset.alertOrder));
  document.querySelectorAll('[data-alert-entry]').forEach(el=>el.onclick=()=>ctx.entryDetails(el.dataset.alertEntry));
 }
 function render(page){if(!ctx.routeAllowed(page)){toast('Seu acesso não permite abrir esta área.');return}ctx.current=page;const routes={home:dashboard,clients:()=>ctx.listPage('clients'),products:()=>ctx.listPage('products'),suppliers:ctx.suppliersPage,'client-new':()=>ctx.formPage('client-new'),'product-new':()=>ctx.formPage('product-new'),quotes:ctx.quotesPage,quote:ctx.quoteForm,view:ctx.printView,receipt:ctx.receiptView,workflow:ctx.workflowPage,finance:ctx.financePage,bank:ctx.bankPage,reports:ctx.reportsPage,assets:ctx.assetsPage,settings:ctx.settingsPage,users:ctx.usersPage};try{(routes[page]||dashboard)()}catch(e){console.error(e);toast('Não foi possível abrir a tela. '+e.message)}}
 function modal(title,body,{wide=false}={}){const d=document.createElement('dialog');if(wide)d.classList.add('wide-dialog');d.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="ghost small" type="button" data-close aria-label="Fechar">${ctx.icon('x')}</button></div>${body}`;document.body.append(d);d.showModal();d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>d.close());d.onclose=()=>d.remove();return d}
 const rpc=(name,body={})=>ctx.api('/rest/v1/rpc/'+name,{method:'POST',body});
 let dashboardRefreshBusy=false,lastDashboardRefresh=0;
 async function refreshDashboard(){
  if(dashboardRefreshBusy||!ctx.session||!ctx.profile?.active||!['home','finance'].includes(ctx.current)||document.hidden||document.querySelector('dialog[open]')||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)||Date.now()-lastDashboardRefresh<55000)return;
  dashboardRefreshBusy=true;lastDashboardRefresh=Date.now();
  try{await ctx.load();if(ctx.session&&!document.hidden&&!document.querySelector('dialog[open]')){if(ctx.current==='home')ctx.render('home');else if(ctx.current==='finance'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))ctx.refreshFinancePage?.()}}catch{}finally{dashboardRefreshBusy=false}
 }
 window.addEventListener('focus',refreshDashboard);
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshDashboard()});
 setInterval(refreshDashboard,60000);
Object.assign(ctx,{quoteRef:quoteReference,toast,shell,head,empty,metric,render,modal,rpc,financeMetrics});
}
